// spec: .qa/e2e/specs/add-candidate.md 3.4 (CHAIN step 1 of 2, one role per file)
// seed: tests/seed.hunter_plus.spec.ts
// Run the chain in order, one worker:
//   npx playwright test tests/add-candidate/chain-daf026-visibility --workers=1 --project=tests
// Creates data: 2 candidates «QA-AUTO-daf026 A<runId>» / «… F<runId>» + 2 submissions to J-49 (no delete in UI — logged to test-data-journal.log).
import { test, expect, Page } from '@playwright/test';
import fs from 'fs';
import path from 'path';
import { openAddCandidate, fillStep1, searchMyCandidates, uniquePhone, stamp, ANON_INFO } from './helpers';

test.use({ storageState: path.join(__dirname, '../../../auth/hunter_plus.json') });
test.describe.configure({ mode: 'serial' });

const HANDOFF = path.join(__dirname, '../../.handoff/daf026-visibility.json');
const JOURNAL = path.join(__dirname, '../../test-data-journal.log');
const J49 = '/collaborations/7e4ad713-60a0-4e68-9926-56e0ee667584';
const FIRST = 'QA-AUTO-daf026';
const FIELD = 'טכנולוגיה, מוצר, דאטה ומערכות מידע';

const runId = stamp();
type Cand = { last: string; phone: string; email: string; answer: string; mode: 'פרופיל אנונימי' | 'פרופיל מלא' };
const anon: Cand = {
  last: `A${runId}`, phone: uniquePhone(), email: `qa-auto-daf026-a${runId}@example.com`,
  answer: `QA-AUTO daf026 anon ${runId}`, mode: 'פרופיל אנונימי',
};
const full: Cand = {
  last: `F${runId}`, phone: '', email: `qa-auto-daf026-f${runId}@example.com`,
  answer: `QA-AUTO daf026 full ${runId}`, mode: 'פרופיל מלא',
};

const created: Cand[] = [];

async function createCandidate(page: Page, c: Cand) {
  const dialog = await openAddCandidate(page);
  // #daf026: no profile-type choice, the info line is shown instead
  await expect(dialog.getByText(ANON_INFO.he)).toBeVisible();
  await expect(dialog.getByRole('radio')).toHaveCount(0);
  await dialog.getByRole('textbox', { name: /^אימייל/ }).fill(c.email);
  await fillStep1(dialog, { first: FIRST, last: c.last, phone: c.phone, field: FIELD });
  await expect(page.locator('#c-ai-summary')).toHaveValue(/\S/, { timeout: 60_000 });
  await dialog.getByRole('button', { name: 'סיום', exact: true }).click();
  await expect(dialog).toBeHidden({ timeout: 30_000 });
  created.push(c);
  const headings = await searchMyCandidates(page, c.last);
  await expect(headings.filter({ hasText: c.last })).toHaveCount(1);
}

async function submitToJ49(page: Page, c: Cand) {
  const name = `${FIRST} ${c.last}`;
  await page.goto(J49);
  const drawer = page.getByRole('dialog', { name: 'פרטי המשרה' });
  await expect(drawer.getByRole('heading', { name: 'QA company post test' })).toBeVisible();
  await drawer.getByRole('searchbox', { name: 'חיפוש מועמד' }).fill(c.last);
  await drawer.getByRole('button', { name: `הגשת ${name} למשרה` }).click();

  const choose = page.getByRole('dialog', { name: new RegExp(`^הגשת .*${c.last}`) });
  await expect(choose.getByRole('heading', { name: 'האם להגיש פרופיל מלא או אנונימי?' })).toBeVisible();
  await choose.getByText(c.mode, { exact: true }).click();
  await expect(choose.getByRole('radio', { name: new RegExp(`^${c.mode}`) })).toBeChecked();
  await expect(choose.getByRole('radio', { name: /^אין צורך ב-NDA/ })).toBeChecked();
  await choose.getByRole('button', { name: 'המשך', exact: true }).click();

  const form = page.getByRole('dialog', { name: `הגשת מועמד: ${name}` });
  await expect(form.getByRole('textbox', { name: 'תקציר המועמד' })).toHaveValue(/\S/, { timeout: 60_000 });
  await form.getByRole('textbox', { name: 'QA test question' }).fill(c.answer);
  const send = form.getByRole('button', { name: 'סיום והגשה', exact: true });
  await expect(send).toBeEnabled({ timeout: 60_000 });
  await send.click();
  await expect(form).toBeHidden({ timeout: 30_000 });
}

test.describe('Candidate added by a headhunter is always anonymous — chain step 1 (#daf026)', () => {
  test.afterAll(() => {
    const at = new Date().toISOString();
    const lines = created.map(
      (c) => `${at} hunter_plus candidate «${FIRST} ${c.last}» (planned J-49 submission: ${c.mode}) (add-candidate 3.4 #daf026, no delete option)\n`,
    );
    fs.appendFileSync(JOURNAL, lines.join(''));
  });

  test('CHAIN 1 — hunter creates 2 candidates without profile choice, submits one anonymous and one full profile to J-49 @desktop @data #daf026', async ({ page }) => {
    test.setTimeout(300_000);
    fs.rmSync(HANDOFF, { force: true });

    // 1–2. Two candidates, no profile-type choice
    await createCandidate(page, anon);
    full.phone = uniquePhone();
    await createCandidate(page, full);

    // 3–4. Anonymous and full-profile submissions to J-49
    await submitToJ49(page, anon);
    await submitToJ49(page, full);

    // 5. Handoff for the company step
    fs.mkdirSync(path.dirname(HANDOFF), { recursive: true });
    fs.writeFileSync(
      HANDOFF,
      JSON.stringify({ runId, first: FIRST, anon, full, createdAt: new Date().toISOString() }, null, 2),
    );
  });
});
